using System.Text.Json;

namespace Fineage.Game.Services;

/// <summary>
/// Mobius <c>handler="…"</c> on etc items that are not <c>ItemSkills</c>
/// (<c>data/item-handlers.json</c>, generated by <c>scripts/gen_item_handlers.py</c>).
/// </summary>
public sealed class ItemHandlerCatalog
{
    public const string FileName = "item-handlers.json";

    static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true
    };

    readonly Dictionary<int, string> _byItem;

    ItemHandlerCatalog(Dictionary<int, string> byItem) => _byItem = byItem;

    public static ItemHandlerCatalog Empty { get; } = new([]);

    public static ItemHandlerCatalog LoadDefault()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "data", FileName);
        if (!File.Exists(path))
            path = Path.Combine(Directory.GetCurrentDirectory(), "data", FileName);
        if (!File.Exists(path))
            throw new FileNotFoundException($"Missing {FileName} under data/.", path);
        return Parse(File.ReadAllText(path), path);
    }

    public static ItemHandlerCatalog Parse(string json, string source = FileName)
    {
        var dto = JsonSerializer.Deserialize<FileDto>(json, JsonOptions)
            ?? throw new InvalidDataException($"{source}: empty item-handlers document.");
        var byItem = new Dictionary<int, string>();
        foreach (var (key, handler) in dto.Items ?? [])
        {
            if (!int.TryParse(key, out int itemId) || itemId <= 0)
                throw new InvalidDataException($"{source}: bad item id '{key}'.");
            if (string.IsNullOrWhiteSpace(handler))
                throw new InvalidDataException($"{source}: item {itemId} has empty handler.");
            if (!byItem.TryAdd(itemId, handler.Trim()))
                throw new InvalidDataException($"{source}: item {itemId} listed twice.");
        }

        return new ItemHandlerCatalog(byItem);
    }

    public bool TryGet(int itemId, out string handler) => _byItem.TryGetValue(itemId, out handler!);

    public IReadOnlyDictionary<int, string> All => _byItem;

    sealed class FileDto
    {
        public Dictionary<string, string>? Items { get; set; }
    }
}
